@startuml
class Customer {
  +vatNumber : string
  +name : string
  +phoneNumber : string
  +address : string
}

class Package {
  +identifierCode : string
  +weight : float
  +deliveryType : string
}

class DeliveryCenter {
  +name : string
  +address : string
}

class Courier {
  +vatNumber : string
  +name : string
  +phoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "1" DeliveryCenter : is associated with
Package "1" -- "1" Customer : recipient
Package "1" -- "1" DeliveryCenter : is routed through
Package "1" -- "0..1" Courier : is assigned to
Courier "1" -- "1" DeliveryCenter : works in
@enduml

